```latex
\noindent \textbf{Processes.}
We consider a static system $\Pi = \{p_1, ..., p_n\}$ of $n$ processes that communicate by sending messages; each process acts as a deterministic state machine.
A Byzantine process behaves arbitrarily, whereas a non-Byzantine process behaves according to its state machine.
Byzantine processes are said to be \emph{faulty}; non-faulty processes are said to be \emph{correct}. 

\noindent \textbf{Values.} We denote the set of values by $\mathsf{Value}$.
Recall that $\mathsf{valid}: \mathsf{Value} \to \{\mathit{true}, \mathit{false}\}$ indicates whether or not a value is valid.

\begin{module} [h]
\caption{\block}
\label{mod:crux}
\footnotesize
\begin{algorithmic}[1]

\Statex \textbf{Parameters:}
\Statex \hskip2em $\mathsf{Time\_Duration}$ $\Delta_{\mathit{shift}}$ \BlueComment{common for all processes}
\Statex \hskip2em $\mathsf{Time\_Duration}$ $\Delta_{\mathit{total}}$ \BlueComment{common for all processes}
\Statex \hskip2em $\mathsf{Value}$ $\mathsf{def}(p_i)$ such that $\mathsf{valid}\big( \mathsf{def}(p_i) \big) = \mathit{true}$, for every correct process $p_i$ \BlueComment{each process $p_i$ has its default value}

\medskip
\Statex \textbf{Events:}
\Statex \hskip2em \emph{request} $\mathsf{propose}(v \in \mathsf{Value})$: a process proposes value $v$.
\Statex \hskip2em \emph{request} $\mathsf{abandon}$: a process abandons (i.e., stops participating in) \block.
\Statex \hskip2em \emph{indication} $\mathsf{validate}(v' \in \mathsf{Value})$: a process validates value $v'$.
\Statex \hskip2em \emph{indication} $\mathsf{decide}(v' \in \mathsf{Value})$: a process decides value $v'$.
\Statex \hskip2em \emph{indication} $\mathsf{completed}$: a process is notified that \block has completed.

\medskip 
\Statex \textbf{Notes:} 
\Statex \hskip2em We assume that every correct process proposes at most once and it does so with a valid value. 
We do not assume that all correct processes \hphantom{aallll}propose.
Note that a correct process can validate a value from \block even if (1) it has not previously proposed, or (2) it has previously \hphantom{aallll}abandoned \block, or (3) it has previously received a $\mathsf{completed}$ indication.
Moreover, a correct process can receive both a $\mathsf{validate}(\cdot)$ and \hphantom{aallll}a $\mathsf{decide}(\cdot)$ indication from \block.
Finally, observe that two correct processes can validate (but not decide!) different values.

\medskip 
\Statex \textbf{Properties:}

\Statex \hskip2em  \emph{Strong validity:} If all correct processes that propose do so with the same value $v$, then no correct process decides or validates any value $v' \neq v$.

\smallskip
\Statex \hskip2em \emph{External validity:} If any correct process decides or validates any value $v$, then $\mathsf{valid}(v) = \mathit{true}$.





\smallskip 
\Statex \hskip2em \emph{Agreement:} If any correct process decides a value $v$, then no correct process validates or decides any value $v' \neq v$.

\smallskip 
\Statex \hskip2em \emph{Integrity:} No correct process decides or receives a $\mathsf{completed}$ indication unless it has previously proposed.

\smallskip 
\Statex \hskip2em \emph{Termination:} If all correct processes propose and no correct process abandons \block, then every correct process eventually receives a $\mathsf{completed}$ \hphantom{allllll}indication.

\smallskip 
\Statex \hskip2em \emph{Totality:} If any correct process receives a $\mathsf{completed}$ indication at some time $\tau$, then every correct process validates a value by time \hphantom{allllll}$\max(\tau, \text{GST}) + 2\delta$.

\smallskip 
\Statex \hskip2em \emph{Synchronicity:} Let $\tau$ denote the first time a correct process proposes to \block.
If (1) $\tau \geq \text{GST}$, (2) all correct processes propose by time \hphantom{allllll}$\tau + \Delta_{\mathit{shift}}$, and (3) no correct process abandons \block by time $\tau + \Delta_{\mathit{total}}$, then every correct process decides by time $\tau + \Delta_{\mathit{total}}$.

\smallskip 
\Statex \hskip2em \emph{Completion time:} If a correct process $p_i$ proposes to \block at some time $\tau \geq \text{GST}$, then $p_i$ does not receive a $\mathsf{completed}$ indication by time \hphantom{allllll}$\tau + \Delta_{\mathit{total}}$.

\end{algorithmic}
\end{module}

The finisher primitive exposes the following interface:
\begin{compactitem}
    \item \textbf{request} $\mathsf{to\_finish}(v \in \mathsf{Value})$: a process aims to finish with value $v$.

    \item \textbf{indication} $\mathsf{finish}(v' \in \mathsf{Value})$: a process finishes with value $v'$.
\end{compactitem}
Every correct process invokes $\mathsf{to\_finish}(\cdot)$ at most once.
Moreover, if any correct process invokes $\mathsf{to\_finish}(v_1)$ and any other correct process invokes $\mathsf{to\_finish}(v_2)$, then $v_1 = v_2$.

The following properties are satisfied by the finisher primitive:
\begin{compactitem}
    \item \emph{Integrity:} If a correct process receives a $\mathsf{finish}(v')$ indication, then a correct process has previously invoked a $\mathsf{to\_finish}(v')$ request.

    \item \emph{Termination:} Let $\tau$ be the first time such that all correct processes have invoked a $\mathsf{to\_finish}(\cdot)$ request by time $\tau$.
    Then, every correct process receives a $\mathsf{finish}(\cdot)$ indication by time $\max(\tau, \text{GST}) + 2\delta$.

    \item \emph{Totality:} If any correct process receives a $\mathsf{finish}(\cdot)$ indication at some time $\tau$, then every correct process receives a $\mathsf{finish}(\cdot)$ indication by time $\max(\tau, \text{GST}) + 2\delta$.
\end{compactitem}

\name's executions unfold in views; $\mathsf{View} = \{1, 2, ...\}$ denotes the set of views.
Moreover, each view is associated with its instance of \block; the instance of \block associated with view $V \in \mathsf{View}$ is denoted by $\mathcal{CX}(V)$ (line~\ref{line:block_instance}).

\begin{algorithm} [h]
\caption{\name: Pseudocode (for process $p_i$)}
\label{algorithm:name_pseudocode_2}
\footnotesize
\begin{algorithmic} [1] 
\State \textbf{Uses:}
\State \hskip2em \block with parameter $\Delta_{\mathit{shift}} = 2\delta$, \textbf{instances} $\mathcal{CX}(V)$, for every $V \in \mathsf{View}$ \label{line:block_instance} \BlueComment{see \Cref{section:block}}
\State \hskip2em Finisher, \textbf{instance} $\mathcal{F}$



\medskip
\State \textbf{Local variables:}
\State \hskip2em $\mathsf{Map}(\mathsf{View} \to \mathsf{Boolean})$ $\mathit{helped}_i \gets \{\mathit{false}, \mathit{false}, ..., \mathit{false}\}$
\State \hskip2em $\mathsf{View}$ $\mathit{view}_i \gets 1$ \label{line:init_view}


\medskip
\State \textbf{upon} $\mathsf{propose}(v \in \mathsf{Value})$: \label{line:name_propose} \BlueComment{start participating in \name}
\State \hskip2em initialize $\mathcal{CX}(V)$ with $\mathsf{def}(p_i) = v$, for every view $V$
\State \hskip2em \textbf{invoke} $\mathcal{CX}(1).\mathsf{propose}(v)$ \BlueComment{start \block associated with view $1$ (i.e., enter view $1$)} \label{line:enter_1}

\medskip
\State \textbf{upon} $\mathcal{CX}(\mathit{view}_i).\mathsf{completed}$: \label{line:view_timer_expire} \BlueComment{current \block instance (i.e., current view) has completed}
\State \hskip2em \textbf{broadcast} $\langle \textsc{start-view}, \mathit{view}_i + 1 \rangle$ \label{line:send_complete_1} \BlueComment{start transiting to the next view}

\medskip
\State \textbf{upon} exists $\mathsf{View}$ $V$ such that $\langle \textsc{start-view}, V \rangle$ is received from $t + 1$ processes and $\mathit{helped}_i[V] = \mathit{false}$: \label{line:receive_plurality}
\State \hskip2em $\mathit{helped}_i[V] \gets \mathit{true}$
\State \hskip2em \textbf{broadcast} $\langle \textsc{start-view}, V \rangle$ \label{line:send_complete_2}






\medskip
\State \textbf{upon} exists $\mathsf{View}$ $V > \mathit{view}_i$ such that $\langle \textsc{start-view}, V \rangle$ is received from $2t + 1$ processes: \label{line:receive_quorum}
\label{line:send_complete_3_prime}
\State \hskip2em \textbf{wait for} $\mathcal{CX}(V - 1).\mathsf{validate}(v \in \mathsf{Value})$ \label{line:wait_to_validate} \BlueComment{wait for a value to propose to the new \block instance}
\State \hskip2em \textbf{invoke} $\mathcal{CX}(\mathit{view}_i).\mathsf{abandon}$ \BlueComment{stop participating in the current \block instance} \label{line:leave_v}
\State \hskip2em \textbf{invoke} $\mathcal{CX}(V).\mathsf{propose}(v)$ \BlueComment{start the new \block instance (i.e., enter new view)}  \label{line:enter_v}
\State \hskip2em $\mathit{view}_i \gets V$ \label{line:update_view_i} \BlueComment{update the current view}




\medskip
\State \textbf{upon} $\mathcal{CX}(\mathit{view}_i).\mathsf{decide}(v' \in \mathsf{Value})$: \label{line:decide_from_core} \BlueComment{decided from \block}
\State \hskip2em \textbf{invoke} $\mathcal{F}.\mathsf{to\_finish}(v')$ \label{line:to_finish_name}



\medskip 
\State \textbf{upon} $\mathcal{F}.\mathsf{finish}(v')$: \label{line:receive_finish_name}
\State \hskip2em \textbf{trigger} $\mathsf{decide}(v')$ \label{line:name_decide} \BlueComment{decide from \name}
\State \hskip2em \textbf{invoke} $\mathcal{CX}(\mathit{view}_i).\mathsf{abandon}$ \BlueComment{stop participating in the current \block instance}
\State \hskip2em \textbf{halt} \BlueComment{stop sending any messages and reacting to any received messages}  \label{line:name_stop} 



\end{algorithmic} 
\end{algorithm}

\begin{lemma} \label{lemma:decide_from_block_propose_the_same}
Let a correct process decide a value $v$ from $\mathcal{CX}(V)$, where $V$ is any view.
If a correct process proposes a value $v'$ to $\mathcal{CX}(V')$, for any view $V' > V$, then $v' = v$. 
\end{lemma}
